export type Id = string | number;

// typeof narrows id to string in the if, number after it.
export function badge(id: Id): string {
  if (typeof id === 'string') return 'LAB-' + id.padStart(4, '0');
  return 'LAB-' + String(id).padStart(4, '0');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { badge } from '../src/badge.ts';

test('string id', () => assert.equal(badge('42'), 'LAB-0042'));
test('number id', () => assert.equal(badge(42), 'LAB-0042'));

