export type Value = string | number | boolean;

export function label(v: Value): string {
  if (typeof v === 'string') return '"' + v + '"';
  if (typeof v === 'number') return String(v);
  return v ? 'on' : 'off';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { label } from '../src/label.ts';

test('string', () => assert.equal(label('dark'), '"dark"'));
test('number', () => assert.equal(label(30), '30'));
test('boolean', () => assert.equal(label(true), 'on'));
test('boolean false', () => assert.equal(label(false), 'off'));

